#include "../src/core/binary_workflows.h"
#include "../src/core/folder_text_rules.h"
#include "../src/core/workflow_views.h"
#include "../src/core/workspace_session.h"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <algorithm>
using namespace simple_editor::core;
int RunWorkflowTests(const std::filesystem::path& root) {
    std::wcout << std::unitbuf;
    int failures = 0; const auto check = [&](bool ok,const wchar_t* label) { std::wcout << (ok ? L"PASS: " : L"FAIL: ") << label << L'\n'; if (!ok) ++failures; }; const auto write = [](const std::filesystem::path& path,const std::vector<std::uint8_t>& bytes) { std::filesystem::create_directories(path.parent_path()); std::ofstream out(path,std::ios::binary); out.write(reinterpret_cast<const char*>(bytes.data()),bytes.size()); }; std::wstring error; std::atomic_bool cancel{false}; SaveControl control; control.cancelled = &cancel;
    const auto path = root / L"glyphs.bin"; std::vector<std::uint8_t> bytes(15,'a'); bytes.insert(bytes.end(),{0xE4,0xB8,0xAD,'z'}); write(path,bytes); BinaryDocument document; document.Open(path.wstring(),&error); std::vector<DecodedGlyph> glyphs;
    check(DecodeHexWindow(document,16,1,HexDecoding::Utf8,&glyphs,&error) && glyphs.size() == 1 && glyphs[0].offset == 15 && glyphs[0].length == 3 && glyphs[0].text == L"\x4E2D",L"UTF-8 Hex decoding maps a continuation-byte viewport to the complete original character");
    const auto utf16 = root / L"surrogate.bin"; write(utf16,{0,0,0x3D,0xD8,0x80,0xDE,0x41,0}); BinaryDocument other; other.Open(utf16.wstring(),&error); check(DecodeHexWindow(other,4,1,HexDecoding::Utf16Le,&glyphs,&error) && glyphs.size() == 1 && glyphs[0].offset == 2 && glyphs[0].length == 4 && glyphs[0].text == L"\U0001F680",L"UTF-16 decoding preserves surrogate pairs and physical offsets across viewport boundaries");
    const auto big5 = root / L"big5.bin"; write(big5,{'x',0xA4,0xA4,'z'}); BinaryDocument legacy; legacy.Open(big5.wstring(),&error); check(DecodeHexWindow(legacy,2,1,HexDecoding::Big5,&glyphs,&error) && glyphs[0].offset == 1 && glyphs[0].length == 2 && glyphs[0].text == L"\x4E2D",L"Big5 decoding uses a proven boundary and selects both source bytes");
    const auto uncertain = root / L"ambiguous.bin"; write(uncertain,std::vector<std::uint8_t>(6000,0xA4)); BinaryDocument ambiguous; ambiguous.Open(uncertain.wstring(),&error); check(DecodeHexWindow(ambiguous,5000,2,HexDecoding::Big5,&glyphs,&error) && glyphs.size() == 2 && !glyphs[0].valid && glyphs[0].length == 1,L"ambiguous legacy-code-page phase is shown as undecoded bytes instead of guessing"); const auto retained = glyphs.size(); check(!DecodeHexWindow(ambiguous,0,65537,HexDecoding::Big5,&glyphs,&error) && glyphs.size() == retained,L"oversized Hex decoding refuses allocation and retains prior glyphs");
    const auto arithmetic = root / L"words.bin"; for (unsigned width : {8u,16u,32u,64u}) { write(arithmetic,std::vector<std::uint8_t>(width / 8,255)); BinaryDocument word; word.Open(arithmetic.wstring(),&error); IntegerTransform operation{IntegerOperation::Add,width,false,1}; std::vector<std::uint8_t> result; const bool applied = TransformIntegers(word,0,word.Size(),operation,{},&error); word.Read(0,static_cast<std::size_t>(word.Size()),&result); check(applied && std::all_of(result.begin(),result.end(),[](auto b) { return b == 0; }) && word.Undo(nullptr),L"unsigned add wraps at the chosen width and retains one Undo transaction"); word.Close(); }
    write(arithmetic,{0x12,0x34}); BinaryDocument word; word.Open(arithmetic.wstring(),&error); IntegerTransform operation{IntegerOperation::Xor,16,false,0xFF}; std::vector<std::uint8_t> transformed; check(TransformIntegers(word,0,2,operation,{},&error) && word.Read(0,2,&transformed) && transformed == std::vector<std::uint8_t>({0x12,0xCB}),L"big-endian XOR transforms numeric words without reversing the surrounding byte order"); operation = {IntegerOperation::ShiftLeft,16,true,16}; check(!TransformIntegers(word,0,2,operation,{},&error) && !TransformIntegers(word,0,1,{IntegerOperation::Add,16,true,1},{},&error),L"invalid shift counts and partial numeric words are refused"); cancel = true; check(!TransformIntegers(word,0,2,{IntegerOperation::Add,16,true,1},control,&error) && word.Read(0,2,&transformed) && transformed[1] == 0xCB,L"cancelled integer operations leave the draft unchanged"); cancel = false;
    const auto strings_path = root / L"strings.bin"; bytes.assign(256 * 1024 - 2,0); const std::string label = "VERSION-1234"; bytes.insert(bytes.end(),label.begin(),label.end()); bytes.insert(bytes.end(),{0,0x41,0,0x42,0,0x43,0,0,0}); write(strings_path,bytes); BinaryDocument strings_doc; strings_doc.Open(strings_path.wstring(),&error); StringExtraction strings; check(ExtractStrings(strings_doc,0,strings_doc.Size(),4,1,{},&strings,&error) && strings.total == 1 && strings.rows[0].text == L"VERSION-1234" && strings.rows[0].offset == 256 * 1024 - 2,L"streaming unknown-string extraction retains ASCII strings crossing input chunks"); check(ExtractStrings(strings_doc,0,strings_doc.Size(),3,2,{},&strings,&error) && std::any_of(strings.rows.begin(),strings.rows.end(),[](const auto& row) { return row.text.find(L"ABC") != std::wstring::npos && row.encoding == L"UTF-16 LE"; }),L"UTF-16 extraction handles both physical byte phases and reports its encoding"); const auto old_total = strings.total; cancel = true; check(!ExtractStrings(strings_doc,0,strings_doc.Size(),3,7,control,&strings,&error) && strings.total == old_total,L"cancelled string extraction retains the previous result"); cancel = false;
    BinaryDocument draft; draft.Open(path.wstring(),&error); draft.Insert(1,{'X'}); std::vector<ModifiedRange> ranges; check(FindModifiedRanges(document,draft,{},&ranges,&error) && !ranges.empty() && ranges[0].state == L"Added" && ranges[0].offset == 1 && ranges[0].length == 1,L"saved-baseline change ranges retain current-draft insertion addresses"); cancel = true; const auto previous_ranges = ranges.size(); check(!FindModifiedRanges(document,draft,control,&ranges,&error) && ranges.size() == previous_ranges,L"cancelled change analysis does not replace prior adopted ranges"); cancel = false;
    const auto left = root / L"rules-left",right = root / L"rules-right"; write(left / L"same.txt",{'x','\r','\n'}); write(right / L"same.txt",{'x','\n'}); write(left / L"invalid.txt",{0,0,'x'}); write(right / L"invalid.txt",{0,0,'y'}); write(left / L"skip.bin",{'a'}); write(right / L"skip.bin",{'b'}); FolderOptions options; options.text_rules = L"enabled=yes\ninclude=*.txt\nencoding=utf8\nignore-eol=yes"; FolderScan scan; check(ScanFolders(left,right,options,cancel,[](unsigned) {},&scan,&error),L"folder scan adopts independent decoded-text rule analysis"); const auto found = std::find_if(scan.rows.begin(),scan.rows.end(),[](const auto& row) { return row.relative == L"same.txt"; }); check(found != scan.rows.end() && found->state == FolderState::Different && found->text_state == L"Equal under text rules",L"rule-equal files preserve their raw different state for synchronization"); if (found != scan.rows.end()) { SyncPlan plan; check(BuildSyncPlan(scan,{static_cast<std::size_t>(found - scan.rows.begin())},true,false,&plan,&error) && plan.operations.size() == 1,L"independent text equality never silently removes a raw synchronization operation"); }
    check(std::any_of(scan.rows.begin(),scan.rows.end(),[](const auto& row) { return row.relative == L"invalid.txt" && row.text_state == L"Text analysis error" && !row.text_error.empty(); }) && std::any_of(scan.rows.begin(),scan.rows.end(),[](const auto& row) { return row.relative == L"skip.bin" && row.text_state.empty(); }),L"text analysis reports invalid inputs explicitly and respects the extension filter"); FolderTextSettings settings; check(!ParseFolderTextSettings(L"enabled=maybe",&settings,&error) && !ParseFolderTextSettings(L"execute=shell",&settings,&error),L"folder rules reject invalid flags and executable/unknown settings");
    std::vector<unsigned char> important(25); important[12] = 1; auto context = BuildContextRows(important,2,{}); check(context.rows.size() == 7 && context.hidden.at(0) == 10 && context.hidden.at(15) == 10,L"comparison context retains nearby source rows and explicit expandable placeholders"); context = BuildContextRows(important,2,{0}); check(context.rows.size() == 16 && !context.hidden.count(0),L"expanding a context placeholder retains source indices instead of changing comparison blocks"); important.assign(25,0); context = BuildContextRows(important,3,{}); check(context.rows.size() == 1 && context.hidden.at(0) == 25,L"entirely equal comparisons retain an expandable unchanged region");
    write(left / L"sub/deep/item.txt",{'a'}); write(right / L"sub/deep/item.txt",{'b'}); ScanFolders(left,right,{},cancel,[](unsigned) {},&scan,&error); const auto leaf = std::find_if(scan.rows.begin(),scan.rows.end(),[](const auto& row) { return row.relative.filename() == L"item.txt"; }); const auto leaf_index = static_cast<std::size_t>(leaf - scan.rows.begin()); auto tree = BuildFolderTreeRows(scan,{leaf_index},{}); check(tree.rows.size() == 1 && scan.rows[tree.rows[0]].relative == L"sub" && tree.differences[tree.rows[0]] == 1,L"folder tree includes filtered-result ancestors and aggregates descendant differences"); std::set<std::size_t> expanded; for (std::size_t i = 0; i < scan.rows.size(); ++i) if (scan.rows[i].left.directory || scan.rows[i].right.directory) expanded.insert(i); tree = BuildFolderTreeRows(scan,{leaf_index},expanded); check(tree.rows.size() == 3 && tree.rows.back() == leaf_index && tree.depth[leaf_index] == 2,L"expanded tree rows refer to original scan identities and physical hierarchy");
    FolderScan deep; std::filesystem::path relative; for (unsigned n = 0; n < 270; ++n) { relative /= L"d"; FolderRow row; row.relative = relative; row.state = FolderState::Equal; row.left.directory = row.right.directory = true; deep.rows.push_back(row); } FolderRow changed; changed.relative = relative / L"leaf.txt"; changed.state = FolderState::Different; deep.rows.push_back(changed); const auto deep_tree = BuildFolderTreeRows(deep,{270},{}); check(deep_tree.rows.size() == 1 && deep_tree.depth.back() == 270 && deep_tree.differences[0] == 1,L"deep folder subtree counts reach every ancestor without clamping the aggregation depth");
    WorkspaceEntry entry; entry.left = path.wstring(); entry.hex_decoding[0] = 4; entry.context_lines = 5; entry.folder_tree = true; entry.folder_filter = 10; entry.folder_text_rules = options.text_rules; const auto workspace = root / L"workflow.ini"; std::vector<WorkspaceEntry> loaded; check(SaveWorkspaceFile(workspace,{entry},&error) && LoadWorkspaceFile(workspace,&loaded,&error) && loaded[0].hex_decoding[0] == 4 && loaded[0].context_lines == 5 && loaded[0].folder_tree && loaded[0].folder_filter == 10 && loaded[0].folder_text_rules == options.text_rules,L"optional workspace fields preserve decoding, folder rules, tree and context settings"); entry.hex_decoding[0] = 5; check(!SaveWorkspaceFile(workspace,{entry},&error),L"invalid decoded-column settings cannot overwrite a valid workspace");
    const auto pair_path = root / L"strings-surrogate.bin"; write(pair_path,{0x41,0,0x3D,0xD8,0x80,0xDE,0x42,0,0,0}); BinaryDocument pair; pair.Open(pair_path.wstring(),&error); check(ExtractStrings(pair,0,pair.Size(),3,2,{},&strings,&error) && std::any_of(strings.rows.begin(),strings.rows.end(),[](const auto& row) { return row.offset == 0 && row.length == 8 && row.text == L"A\U0001F680B"; }),L"UTF-16 string extraction counts complete Unicode characters and original surrogate bytes");
    for (const auto& test : std::vector<std::pair<IntegerOperation,unsigned>>{{IntegerOperation::And,0},{IntegerOperation::Or,255},{IntegerOperation::Subtract,0},{IntegerOperation::ShiftLeft,0xF0},{IntegerOperation::ShiftRight,0x0F}}) { const auto file = root / L"operator.bin"; const unsigned input = test.first == IntegerOperation::And ? 0xF0 : test.first == IntegerOperation::Or ? 0 : test.first == IntegerOperation::Subtract ? 1 : test.first == IntegerOperation::ShiftLeft ? 0x0F : 0xF0; write(file,{static_cast<std::uint8_t>(input)}); BinaryDocument op; op.Open(file.wstring(),&error); const auto operand = test.first == IntegerOperation::And ? 0x0Fu : test.first == IntegerOperation::Or ? 0xFFu : test.first == IntegerOperation::Subtract ? 1u : 4u; check(TransformIntegers(op,0,1,{test.first,8,true,operand},{},&error) && op.Read(0,1,&transformed) && transformed[0] == test.second,L"unsigned mask, subtraction and shift operations produce their explicit fixed-width result"); }
    const auto preview_path = root / L"preview-surrogate.bin"; bytes.clear(); for (unsigned i = 0; i < 127; ++i) { bytes.push_back('A'); bytes.push_back(0); } bytes.insert(bytes.end(),{0x3D,0xD8,0x80,0xDE,'B',0,0,0}); write(preview_path,bytes); BinaryDocument preview; preview.Open(preview_path.wstring(),&error); check(ExtractStrings(preview,0,preview.Size(),4,2,{},&strings,&error) && std::any_of(strings.rows.begin(),strings.rows.end(),[](const auto& row) { return row.offset == 0 && row.length == 260 && row.text == std::wstring(127,L'A'); }),L"a bounded Unicode preview remains a true prefix when a surrogate pair would cross its unit budget");
    return failures;
}
